// sketch.ino — ESP32-S3 (USB-OTG)
// Матрица 4x4: кнопки 1-12 (ряды 4,5,6)
// Прямые кнопки на GPIO 15-18: кнопки 13-16 (кнопка между пином и GND)
#include "USB.h"
#include "USBHIDKeyboard.h"
USBHIDKeyboard Keyboard;

// ---------- Матрица ----------
const uint8_t ROW_PINS[4] = {4, 5, 6, 7};       // строки: INPUT_PULLUP
const uint8_t COL_PINS_M[4] = {10, 11, 12, 13}; // столбцы: OUTPUT
bool prevState[16] = {false};

// ---------- Прямые кнопки 13-16 ----------
const uint8_t DIRECT_PINS[4] = {15, 16, 17, 18};
bool prevDirect[4] = {false};

// ---------- Кириллица через буфер обмена (base64, UTF-16LE) ----------
const char* B64_SCHOOL =
  "UwBlAHQALQBDAGwAaQBwAGIAbwBhAHIAZAAgAC0AVgBhAGwAdQBlACAAIgAfBD4ENAQ6BDsETgRHBDUEPQQ4BDUEIAA6BCAAQQQ4BEEEQgQ1BDwENQQgAD4EMQRABDAENwQ+BDIEMAQ9BDgETwQgAEgEOgQ+BDsESwQgADIANwAsAGAAbgAjBDQEMAQ7BDUEPQQ4BDUEIAA0BDAEPQQ9BEsERQQuAC4ALgAiAA==";
const char* B64_WATCHING =
  "UwBlAHQALQBDAGwAaQBwAGIAbwBhAHIAZAAgAC0AVgBhAGwAdQBlACAAIgAvBCAAMgRBBFEEIAAyBDgENgRDBC4AIAAfBEAEPgQ0BD4EOwQ2BDAEOQQgAEAEMAQxBD4EQgQwBEIETAQuAC4ALgAiAA==";

// Офлайн-скример: чёрный экран, красный текст, поверх всего
const char* B64_SCARE =
  "";

// ---------- Хелперы ----------
void pressEnter() { Keyboard.press(KEY_RETURN); delay(40); Keyboard.releaseAll(); }

void combo(uint8_t k1, uint8_t k2) {
  Keyboard.press(k1); delay(30); Keyboard.press(k2);
  delay(60); Keyboard.releaseAll();
}
void combo3(uint8_t k1, uint8_t k2, uint8_t k3) {
  Keyboard.press(k1); delay(20); Keyboard.press(k2); delay(20); Keyboard.press(k3);
  delay(60); Keyboard.releaseAll();
}

void runWinR(const char* cmd) {
  combo(KEY_LEFT_GUI, 'r');
  delay(600);
  Keyboard.print(cmd);
  pressEnter();
}

void fullscreen() {
  Keyboard.press(KEY_F11); delay(50); Keyboard.releaseAll();
}

// Кириллица: PowerShell кладёт текст в буфер, блокнот вставляет
void notepadPaste(const char* b64) {
  runWinR("powershell -NoProfile -EncodedCommand ");
  Keyboard.print(b64);
  pressEnter();
  delay(3000);
  runWinR("notepad");
  delay(2500);
  combo(KEY_LEFT_CTRL, 'v');
}

// ---------- Действия ----------
void actGreenFlood() {          // 1
  runWinR("cmd /k \"color 2&for /l %i in (1,0,2) do @dir /s\"");
  delay(1500);
  fullscreen();
}
void actSchoolNotepad() { notepadPaste(B64_SCHOOL); }   // 2
void actShowDesktop()   { combo(KEY_LEFT_GUI, 'd'); }   // 3
void actCloseBrowser()  { combo(KEY_LEFT_ALT, KEY_F4); }// 4
void actScarePic() {          // 5: офлайн-скример вместо картинки
  runWinR("powershell -NoProfile -WindowStyle Hidden -EncodedCommand ");
  Keyboard.print(B64_SCARE);
  pressEnter();
}
void actCalc()          { runWinR("calc"); }            // 6
void actFlipScreen()    { combo3(KEY_LEFT_CTRL, KEY_LEFT_ALT, KEY_DOWN_ARROW); } // 7
void actRickroll() {            // 8
  runWinR("https://www.youtube.com/watch?v=dQw4w9WgXcQ");
  delay(5000);
  fullscreen();
}
void actHacker() {              // 9
  runWinR("cmd /k \"color 2&for /l %i in (1,0,2) do @tree /f\"");
  delay(1500);
  fullscreen();
}
void actInvertColors()  { combo3(KEY_LEFT_CTRL, KEY_LEFT_GUI, 'c'); } // 10
void actNotepadStorm()  { for (int i = 0; i < 5; i++) { runWinR("notepad"); delay(800); } } // 11
void actLockPC()        { combo(KEY_LEFT_GUI, 'l'); }   // 12
void actVolumeMax() {           // 13
  for (int i = 0; i < 50; i++) {
    Keyboard.press(KEY_MEDIA_VOLUME_UP);
    delay(10); Keyboard.release(KEY_MEDIA_VOLUME_UP);
    delay(10);
  }
}
void actWatching() { notepadPaste(B64_WATCHING); }      // 14
void actSearch() {              // 15
  runWinR("https://www.google.com/search?q=how+to+track+my+colleague+location");
}
void actShutdown() {            // 16: выключение ПК
  runWinR("shutdown /s /t 0");
}

void doAction(uint8_t n) {
  switch (n) {
    case 1:  actGreenFlood();             break;
    case 2:  actSchoolNotepad();          break;
    case 3:  actShowDesktop();            break;
    case 4:  actCloseBrowser();           break;
    case 5:  actScarePic();               break;
    case 6:  actCalc();                   break;
    case 7:  actFlipScreen();             break;
    case 8:  actRickroll();               break;
    case 9:  actHacker();                 break;
    case 10: actInvertColors();           break;
    case 11: actNotepadStorm();           break;
    case 12: actLockPC();                 break;
    case 13: actVolumeMax();              break;
    case 14: actWatching();               break;
    case 15: actSearch();                 break;
    case 16: actShutdown();               break;
  }
}

// ---------- Опрос матрицы: кнопка R*4 + C + 1; ряд 4 (13-16) пустой ----------
void setup() {
  for (uint8_t r = 0; r < 4; r++) pinMode(ROW_PINS[r], INPUT_PULLUP);
  for (uint8_t c = 0; c < 4; c++) {
    pinMode(COL_PINS_M[c], OUTPUT);
    digitalWrite(COL_PINS_M[c], HIGH);
  }
  for (uint8_t i = 0; i < 4; i++) pinMode(DIRECT_PINS[i], INPUT_PULLUP);

  Keyboard.begin();
  USB.begin();
  delay(3000);
}

void loop() {
  // Прямые кнопки 13-16
  for (uint8_t i = 0; i < 4; i++) {
    bool now = (digitalRead(DIRECT_PINS[i]) == LOW);
    if (now && !prevDirect[i]) {
      delay(30);
      doAction(13 + i);          // 15->13, 16->14, 17->15, 18->16
      delay(300);
    }
    prevDirect[i] = now;
  }

  // Матрица
  for (uint8_t c = 0; c < 4; c++) {
    digitalWrite(COL_PINS_M[c], LOW);
    delayMicroseconds(50);
    for (uint8_t r = 0; r < 4; r++) {
      bool now = (digitalRead(ROW_PINS[r]) == LOW);
      if (now && !prevState[r * 4 + c]) {
        delay(30);
        uint8_t n = r * 4 + c + 1;
        if (n <= 12) doAction(n);   // ряд 4 не подключён — игнорируем
        delay(300);
      }
      prevState[r * 4 + c] = now;
    }
    digitalWrite(COL_PINS_M[c], HIGH);
  }
}
